/**
 * In-memory PlatformServices implementation for the Vite dev server.
 *
 * Lets games exercise `this.services.*` locally without the production bridge.
 * Not exported from the public barrel — only the dev server constructs it.
 */

import type {
  PlatformServices,
  NotificationSendRequest,
  LeaderboardService,
  UgcService,
  SimulationService,
  EconomyService,
  EconomyClaimResult,
} from './PlatformServices'

interface PlayerSimState {
  inventory: Record<string, number>
}

class MockSimulationService implements SimulationService {
  private readonly players = new Map<string, PlayerSimState>()

  private ensure(playerId: string): PlayerSimState {
    let state = this.players.get(playerId)
    if (!state) {
      state = { inventory: {} }
      this.players.set(playerId, state)
    }
    return state
  }

  async getState(playerId: string): Promise<Record<string, unknown>> {
    const state = this.ensure(playerId)
    return { inventory: { ...state.inventory } }
  }

  async executeRecipe(
    playerId: string,
    recipeId: string,
    input?: Record<string, unknown>,
  ): Promise<Record<string, unknown>> {
    const state = this.ensure(playerId)

    // Consume each input key, clamping at zero so the inventory never goes negative.
    for (const [key, amount] of Object.entries(input ?? {})) {
      const consumed = typeof amount === 'number' ? amount : 0
      const current = state.inventory[key] ?? 0
      state.inventory[key] = Math.max(0, current - consumed)
    }

    const outputKey = `output:${recipeId}`
    state.inventory[outputKey] = (state.inventory[outputKey] ?? 0) + 1

    return { inventory: { ...state.inventory }, recipeId, executed: true }
  }

  async getActiveRuns(_playerId: string): Promise<Array<Record<string, unknown>>> {
    return []
  }

  async getAvailableRecipes(_playerId: string): Promise<Array<Record<string, unknown>>> {
    return []
  }

  async grantMeta(playerId: string, entityId: string, amount: number): Promise<void> {
    const state = this.ensure(playerId)
    state.inventory[entityId] = (state.inventory[entityId] ?? 0) + amount
  }
}

class MockEconomyService implements EconomyService {
  private readonly pools = new Map<string, number>()

  async claim(poolId: string, amount: number, opts?: { allowPartial?: boolean }): Promise<EconomyClaimResult> {
    const remaining = this.pools.get(poolId) ?? 0
    // Mirrors the authoritative settlement in
    // server/game-server/src/services/economy/pools.ts (including the partial default) — keep in sync.
    const allowPartial = opts?.allowPartial ?? true
    const granted = allowPartial ? Math.min(amount, Math.max(0, remaining)) : amount <= remaining ? amount : 0
    const next = remaining - granted
    this.pools.set(poolId, next)
    return { granted, remaining: next }
  }

  async contribute(poolId: string, amount: number): Promise<{ remaining: number }> {
    const next = (this.pools.get(poolId) ?? 0) + amount
    this.pools.set(poolId, next)
    return { remaining: next }
  }

  async remaining(poolId: string): Promise<number> {
    return this.pools.get(poolId) ?? 0
  }
}

const mockLeaderboard: LeaderboardService = {
  async submitScore(): Promise<void> {},
  async getTop(): Promise<Array<{ profileId: string; score: number; rank: number }>> {
    return []
  },
}

const mockUgc: UgcService = {
  async get(): Promise<Record<string, unknown> | null> {
    return null
  },
  async recordUse(): Promise<void> {},
}

export class MockPlatformServices implements PlatformServices {
  readonly simulation: SimulationService = new MockSimulationService()
  readonly economy: EconomyService = new MockEconomyService()
  readonly leaderboard: LeaderboardService = mockLeaderboard
  readonly ugc: UgcService = mockUgc
  readonly notifications = {
    async send(request: NotificationSendRequest): Promise<void> {
      console.log('[mock notify]', request)
    },
  }

  private readonly gameConfig: Record<string, unknown>

  constructor(opts: { gameConfig?: Record<string, unknown> } = {}) {
    this.gameConfig = opts.gameConfig ?? {}
  }

  // Arrow-function field (not a prototype method) so it survives an object
  // spread when the dev server shallow-merges per-game overrides.
  getGameConfig = (): Promise<Record<string, unknown>> => Promise.resolve(this.gameConfig)
}
