/**
 * Local WebSocket room server for `vite dev`.
 * Runs rooms in-process (no Worker Threads, no Firebase auth, no persistence).
 * Uses Vite's ssrLoadModule() for automatic HMR of room code.
 */

import type {ViteDevServer} from 'vite'
import http from 'http'
import {WebSocket, WebSocketServer} from 'ws'
import type {
  JoinResult,
  LeaveReason,
  Player,
  PlayerJoinData,
  RoomConfig,
  RoomProtocol,
  PlatformServices,
  RoomsConfigFile,
  RoomTypeDefinition
} from '../../mp/server'
import {Clock, GameRoom, Logger, SYSTEM_MSG_DISCONNECTED, SYSTEM_MSG_RECONNECTED} from '../../mp/server'
import {MockPlatformServices} from '../../mp/server/MockPlatformServices'
import type {RealtimeRoomSummary} from '../../mp/shared'
import path from 'path'
import fs from 'fs'
import { resolveRoomsConfigPath } from './configPath'

/**
 * A constructable deterministic-room class. Typed `=> unknown` (NOT
 * `=> GameRoom<any>`) because the concrete implementation
 * (`@series-inc/rundot-syncplay`'s `DevSyncplayAuthorityRoom`) does not extend
 * `GameRoom` — the dev-server only `new`s it for its constructor side-effect
 * (wiring the protocol's inbound handlers) and never touches the GameRoom
 * surface. Keeping the option loose lets consumers pass the class with no cast;
 * the localized `as unknown as` cast lives at the `new` site below.
 */
export type DeterministicRoomClass = new (...args: any[]) => unknown

export interface DevServerOptions {
  /** Port for the local WS room server (default: 9001) */
  port?: number
  /** Whether to run rooms in Worker Threads (default: false = in-process) */
  threaded?: boolean
  /** Path to rooms.config.json (default: auto-detect from project root) */
  configPath?: string
  /** Vite project root — base for resolving room.file paths and the default config path */
  projectRoot?: string
  /** Per-sub-service overrides shallow-merged over the default MockPlatformServices. */
  mockServices?: Partial<PlatformServices>
  /** Static object returned by `services.getGameConfig()` in dev. */
  gameConfig?: Record<string, unknown>
  /**
   * Room class instantiated for `deterministic: true` rooms. Injected by the
   * consumer (`@series-inc/rundot-syncplay`'s `DevSyncplayAuthorityRoom`) so the
   * SDK stays engine-agnostic. Omitting it makes deterministic rooms throw.
   */
  deterministicRoomClass?: DeterministicRoomClass
}

const DEFAULT_RECONNECT_TIMEOUT_MS = 30_000

/** Max sendTo frames buffered per joiner before drop-oldest kicks in. */
const PENDING_JOIN_SENDS_CAP = 512

const DEFAULT_DEV_PORT = 9001
const LOG_PREFIX = '[RUN:multiplayer]'
const AUTH_TIMEOUT_MS = 10_000
const DEFAULT_MAX_PLAYERS = 10
const CORS_HEADERS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
}

// ── Matchmaking criteria (WS6) ────────────────────────────────────────────────
// Replicated from server/mp-room-server/src/rooms/criteriaMatch.ts (separate
// package, not importable). A candidate matches iff every requested key equals
// the room's stored value; an omitted/empty request matches everything.
function criteriaMatches(
  roomCriteria: Record<string, string | number>,
  requested?: Record<string, string | number>,
): boolean {
  if (!requested) return true
  const keys = Object.keys(requested)
  if (keys.length === 0) return true
  for (const key of keys) {
    if (roomCriteria[key] !== requested[key]) return false
  }
  return true
}

interface CreateRoomOptions {
  criteria?: Record<string, string | number>
  createOptions?: { maxPlayers?: number; isPrivate?: boolean; metadata?: Record<string, unknown> }
}

// ── DevTicketStore ──────────────────────────────────────────────────────────

interface DevTicket {
  ticketId: string
  profileId: string
  username: string
  avatarUrl: string | null
  gameId: string
  roomType: string
  action: 'create' | 'joinOrCreate' | 'joinByCode'
  roomCode?: string
  criteria?: Record<string, string | number>
  createOptions?: { maxPlayers?: number; isPrivate?: boolean; metadata?: Record<string, unknown> }
  createdAt: number
}

class DevTicketStore {
  private tickets = new Map<string, DevTicket>()
  private playerCounter = 0

  create(body: {
    gameId?: string
    roomType?: string
    action?: string
    roomCode?: string
    profileId?: string
    username?: string
    avatarUrl?: string | null
    criteria?: Record<string, string | number>
    createOptions?: { maxPlayers?: number; isPrivate?: boolean; metadata?: Record<string, unknown> }
  }): DevTicket {
    this.playerCounter++
    const ticketId = `dev-ticket-${Date.now()}-${this.playerCounter}`
    const profileId = body.profileId || `dev-player-${this.playerCounter}`
    const ticket: DevTicket = {
      ticketId,
      profileId,
      username: body.username ?? `Player ${this.playerCounter}`,
      avatarUrl: body.avatarUrl ?? null,
      gameId: body.gameId ?? 'dev-game',
      roomType: body.roomType ?? 'default',
      action: (body.action as DevTicket['action']) ?? 'joinOrCreate',
      roomCode: body.roomCode,
      criteria: body.criteria,
      createOptions: body.createOptions,
      createdAt: Date.now(),
    }
    this.tickets.set(ticketId, ticket)
    return ticket
  }

  redeem(ticketId: string): DevTicket | null {
    const ticket = this.tickets.get(ticketId)
    if (!ticket) return null
    this.tickets.delete(ticketId)
    return ticket
  }
}

// ── DevRoomInstance ─────────────────────────────────────────────────────────

/**
 * Per-player connection state. A rostered player is either live on a specific
 * socket or detached during their grace window. Carrying the socket in the
 * Connected state makes the prod stale-close guard fall out of the type: a close
 * event only matters when its socket equals the player's current Connected socket.
 */
type PlayerConnState =
  | { status: 'connected'; ws: WebSocket }
  | { status: 'disconnected' }

class DevRoomInstance {
  readonly roomId: string
  readonly roomType: string
  readonly roomCode: string
  readonly maxPlayers: number
  readonly isPrivate: boolean
  readonly criteria: Record<string, string | number>
  readonly metadata: Record<string, unknown>
  readonly reconnectTimeoutMs: number
  readonly allowReconnect: boolean
  readonly protocol: RoomProtocol
  private readonly playerConns = new Map<string, PlayerConnState>()
  /**
   * Outboxes for players who have begun joining (the user's onPlayerJoin hook can
   * `sendTo` them — the late-joiner history-replay pattern) but whose socket is
   * not yet registered in playerConns. Keyed by playerId. Opened in joinPlayer
   * before the hook runs, drained+deleted by flushJoinSends after room:joined,
   * discarded on a failed/aborted join.
   */
  private readonly pendingJoinSends = new Map<string, object[]>()
  private readonly logger: Logger
  private readonly onPlayerRemoved: (playerId: string) => void
  private disposed = false

  constructor(
    roomId: string,
    roomType: string,
    roomCode: string,
    RoomClass: new (...args: any[]) => GameRoom<any>,
    config: RoomConfig,
    services: PlatformServices,
    onPlayerRemoved: (playerId: string) => void,
    opts?: {
      criteria?: Record<string, string | number>
      metadata?: Record<string, unknown>
      maxPlayersOverride?: number
      isPrivate?: boolean
      deterministic?: RoomTypeDefinition['deterministic']
    },
  ) {
    this.roomId = roomId
    this.roomType = roomType
    this.roomCode = roomCode
    this.criteria = opts?.criteria ?? {}
    this.metadata = opts?.metadata ?? {}
    this.isPrivate = opts?.isPrivate ?? false
    // Every roster removal calls back here so the manager can clear the matching
    // grace entry — no removal path (kick, dispose, eviction) can leave an orphan timer.
    this.onPlayerRemoved = onPlayerRemoved

    const roomConfig: RoomConfig = {
      maxPlayers: DEFAULT_MAX_PLAYERS,
      idleTimeout: 300,
      autoPersist: false,
      ...config,
    }
    const baseMaxPlayers = roomConfig.maxPlayers ?? DEFAULT_MAX_PLAYERS
    // A ticket may lower capacity but never raise the configured cap.
    this.maxPlayers = opts?.maxPlayersOverride !== undefined
      ? Math.min(opts.maxPlayersOverride, baseMaxPlayers)
      : baseMaxPlayers
    this.reconnectTimeoutMs = typeof roomConfig.reconnectTimeout === 'number'
      ? roomConfig.reconnectTimeout * 1000
      : DEFAULT_RECONNECT_TIMEOUT_MS
    // Prod doesn't yet enforce allowReconnect, but the dev server honors the
    // documented knob: an allowReconnect:false room removes the player on close
    // instead of silently gaining a grace window.
    this.allowReconnect = roomConfig.allowReconnect !== false

    const clock = new Clock()
    const logger = new Logger({ roomId, roomType })
    this.logger = logger

    const protocol = {
      broadcast: (msgType: string, data: unknown) => this.broadcastMsg({ type: 'room:broadcast', msgType, data }),
      sendTo: (playerId: string, msgType: string, data: unknown) => this.sendToPlayer(playerId, { type: 'room:sendTo', msgType, data }),
      kick: (playerId: string, reason?: string) => this.handleKick(playerId, reason),
      lock: () => { /* no-op in dev */ },
      unlock: () => { /* no-op in dev */ },
      persist: () => { /* no persistence in dev */ },

      // Inbound — populated by GameRoom constructor
      handleCreate: () => Promise.resolve(),
      handleRestore: () => Promise.resolve(),
      handleJoin: () => Promise.resolve({ accepted: false, reason: 'Not initialized' } as JoinResult),
      handleMessage: () => Promise.resolve(),
      handleLeave: () => Promise.resolve(),
      handleDispose: () => Promise.resolve(),
      handleTick: () => Promise.resolve(),

      // Serialization — populated by GameRoom constructor
      serializePersistState: () => ({} as Record<string, unknown>),
      getLocked: () => false,
      getPlayers: () => new Map() as ReadonlyMap<string, Player>,
    } satisfies RoomProtocol
    this.protocol = protocol

    // Deterministic rooms derive the engine's fixed `playerCount` from
    // config.maxPlayers, but joins are gated on this.maxPlayers (possibly
    // ticket-lowered via createOptions). If those disagree the authority waits
    // forever for a full room (waitForFullRoom) or simulates phantom neutral
    // slots — a silent dev/prod divergence, since RoomManager hands the prod
    // worker the effective capacity the same way (RoomManager.ts:490-497).
    const syncplayRuntime = opts?.metadata?.syncplayRuntime
    const effectiveRoomConfig: RoomConfig = opts?.deterministic !== undefined
      ? {
          ...roomConfig,
          deterministic: opts.deterministic,
          maxPlayers: this.maxPlayers,
          ...(syncplayRuntime === undefined ? {} : { syncplayRuntime }),
        } as RoomConfig
      : roomConfig
    new RoomClass({ protocol, roomId, roomType, config: Object.freeze(effectiveRoomConfig), players: new Map(), clock, log: logger, services })
  }

  async initialize(): Promise<void> {
    await this.protocol.handleCreate()
  }

  async joinPlayer(data: PlayerJoinData, ws: WebSocket): Promise<{ player: Player }> {
    // Open the joiner's outbox BEFORE running onPlayerJoin: a `sendTo(player.id, …)`
    // inside the hook arrives before the socket is registered below, so buffer it
    // instead of dropping. The buffer is flushed by flushJoinSends AFTER room:joined
    // (not here — the ack hasn't been sent yet), or discarded on a failed join.
    this.pendingJoinSends.set(data.id, [])
    const result = await this.protocol.handleJoin(data)
    if (!result.accepted) throw new Error(`Join rejected: ${result.reason}`)

    // Notify existing players before adding the new socket
    this.broadcastMsg({
      type: 'room:playerJoined',
      playerId: data.id,
      username: data.username,
      avatarUrl: data.avatarUrl ?? null,
    })

    this.playerConns.set(data.id, { status: 'connected', ws })
    return { player: result.player }
  }

  /**
   * True only when `ws` is the player's current live socket. A delayed close on a
   * stale socket (the client already reconnected on a new one, or the player has
   * already been detached) returns false, so the stale close is a no-op.
   */
  isCurrentSocket(playerId: string, ws: WebSocket): boolean {
    const conn = this.playerConns.get(playerId)
    return conn?.status === 'connected' && conn.ws === ws
  }

  /** True when the player is rostered but has no live socket (in grace). */
  isDisconnected(playerId: string): boolean {
    return this.playerConns.get(playerId)?.status === 'disconnected'
  }

  async handleMessage(playerId: string, msgType: string, data: unknown): Promise<void> {
    if (this.disposed) return
    await this.protocol.handleMessage(playerId, msgType, data)
  }

  async removePlayer(playerId: string, reason: LeaveReason = 'leave'): Promise<void> {
    // A player may already have their socket detached (disconnected, mid grace
    // period); membership in the room roster is the source of truth, not the socket.
    if (!this.protocol.getPlayers().has(playerId)) return
    this.playerConns.delete(playerId)
    this.onPlayerRemoved(playerId)
    await this.protocol.handleLeave(playerId, reason)

    // Notify remaining players
    this.broadcastMsg({ type: 'room:playerLeft', playerId })
  }

  /**
   * Detach a player's socket but keep them in the room's player roster for the
   * grace period. Flips the GameRoom player's `connected` flag via the system
   * message and notifies the remaining players.
   */
  async markDisconnected(playerId: string, reconnectTimeoutMs: number): Promise<void> {
    const conn = this.playerConns.get(playerId)
    if (conn?.status !== 'connected') return
    this.playerConns.set(playerId, { status: 'disconnected' })
    await this.protocol.handleMessage(playerId, SYSTEM_MSG_DISCONNECTED, {})
    this.broadcastMsg({ type: 'room:playerDisconnected', playerId, reconnectTimeout: reconnectTimeoutMs })
  }

  /**
   * Re-attach a returning player's socket within the grace period. Flips the
   * `connected` flag back on and notifies the remaining players.
   */
  async reattach(playerId: string, ws: WebSocket): Promise<void> {
    this.playerConns.set(playerId, { status: 'connected', ws })
    await this.protocol.handleMessage(playerId, SYSTEM_MSG_RECONNECTED, {})
    this.broadcastMsg({ type: 'room:playerReconnected', playerId })
  }

  get playerCount(): number {
    return this.protocol.getPlayers().size
  }

  get playerIds(): string[] {
    return [...this.protocol.getPlayers().keys()]
  }

  get isEmpty(): boolean {
    return this.protocol.getPlayers().size === 0
  }

  hasPlayer(playerId: string): boolean {
    return this.protocol.getPlayers().has(playerId)
  }

  async dispose(): Promise<void> {
    if (this.disposed) return
    this.disposed = true

    await this.protocol.handleDispose()

    // Close all live player sockets and clear any grace entries the disposed
    // players still hold, so disposing a room can't strand a timer either.
    for (const [playerId, conn] of this.playerConns) {
      if (conn.status === 'connected' && conn.ws.readyState === WebSocket.OPEN) {
        conn.ws.close(1000, 'Room disposed')
      }
      this.onPlayerRemoved(playerId)
    }
    this.playerConns.clear()
    // Drop any outbox a still-mid-join player left behind so dispose strands nothing.
    this.pendingJoinSends.clear()
  }

  private broadcastMsg(msg: object): void {
    const json = JSON.stringify(msg)
    for (const conn of this.playerConns.values()) {
      if (conn.status === 'connected' && conn.ws.readyState === WebSocket.OPEN) {
        conn.ws.send(json)
      }
    }
  }

  /** The player's socket if it is registered, connected, and OPEN; else undefined. */
  private liveSocket(playerId: string): WebSocket | undefined {
    const conn = this.playerConns.get(playerId)
    return conn?.status === 'connected' && conn.ws.readyState === WebSocket.OPEN ? conn.ws : undefined
  }

  private sendToPlayer(playerId: string, msg: object): void {
    const ws = this.liveSocket(playerId)
    if (ws) {
      ws.send(JSON.stringify(msg))
      return
    }

    // No live socket yet, but the player is mid-join with an open outbox: buffer
    // for replay on flushJoinSends instead of dropping. (If neither, no-op.)
    const outbox = this.pendingJoinSends.get(playerId)
    if (outbox) {
      outbox.push(msg)
      if (outbox.length > PENDING_JOIN_SENDS_CAP) {
        // Drop-oldest: the replay becomes non-contiguous, which a game may notice,
        // but the alternative is unbounded memory on a misbehaving hook.
        outbox.shift()
        this.logger.warn(
          `Pending join outbox for ${playerId} exceeded ${PENDING_JOIN_SENDS_CAP}; dropped oldest message`,
        )
      }
    }
  }

  /**
   * Drain the joiner's buffered sendTo frames to their now-live socket in FIFO
   * order, exactly once, then delete the outbox. Called after the room:joined ack
   * so replays hit the wire after it. If the player has no live OPEN socket (they
   * disconnected mid-join), nothing is sent but the outbox is still cleared.
   */
  flushJoinSends(playerId: string): void {
    const outbox = this.pendingJoinSends.get(playerId)
    this.pendingJoinSends.delete(playerId)
    if (!outbox) return
    const ws = this.liveSocket(playerId)
    if (!ws) return
    for (const msg of outbox) {
      ws.send(JSON.stringify(msg))
    }
  }

  /** Drop a joiner's outbox without sending. Used when a join fails or is aborted. */
  discardJoinSends(playerId: string): void {
    this.pendingJoinSends.delete(playerId)
  }

  private handleKick(playerId: string, reason?: string): void {
    const conn = this.playerConns.get(playerId)
    const ws = conn?.status === 'connected' ? conn.ws : undefined
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: 'room:error', code: 'KICKED', message: reason ?? 'Kicked from room' }))
      ws.close(4003, reason ?? 'Kicked')
    }
    this.removePlayer(playerId, 'kick').catch((err) => {
      console.error(`${LOG_PREFIX} Error during kick cleanup:`, err)
    })
  }
}

// ── DevRoomManager ──────────────────────────────────────────────────────────

function generateRoomCode(): string {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789' // no I/O/0/1 to avoid confusion
  let code = ''
  for (let i = 0; i < 6; i++) {
    code += chars[Math.floor(Math.random() * chars.length)]
  }
  return code
}

function generateRoomId(): string {
  return `dev-room-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

/** A player held in its room's grace window, with the timer that will evict it. */
interface DisconnectedPlayer {
  roomId: string
  playerId: string
  timer: ReturnType<typeof setTimeout>
}

// Exported for unit-testing the reconnect/disconnect state machine. Not re-exported
// from the package barrel — the public surface is still only the Vite plugin.
export class DevRoomManager {
  private rooms = new Map<string, DevRoomInstance>()
  private roomCodes = new Map<string, string>() // code → roomId
  private singletonRooms = new Map<string, string>() // roomType → roomId
  private disconnectedPlayers = new Map<string, DisconnectedPlayer>() // `${roomId}:${playerId}` → entry
  private viteServer: ViteDevServer
  private configPath: string
  private projectRoot: string
  private services: PlatformServices
  private roomsConfig: RoomsConfigFile | null = null
  private deterministicRoomClass?: DeterministicRoomClass

  constructor(
    viteServer: ViteDevServer,
    configPath: string,
    projectRoot: string,
    services: PlatformServices,
    deterministicRoomClass?: DeterministicRoomClass,
  ) {
    this.viteServer = viteServer
    this.configPath = configPath
    this.projectRoot = projectRoot
    this.services = services
    this.deterministicRoomClass = deterministicRoomClass
  }

  private disconnectKey(roomId: string, playerId: string): string {
    return `${roomId}:${playerId}`
  }

  /**
   * Clear a profile's grace entry for a room: cancel the timer and drop the map
   * key. The single reconciliation point for the grace map — every roster removal
   * (eviction timer fire, kick, dispose, join-elsewhere) routes through here, so a
   * grace timer exists iff the profile is currently mid-grace on that room.
   */
  private clearGrace(roomId: string, playerId: string): void {
    const key = this.disconnectKey(roomId, playerId)
    const entry = this.disconnectedPlayers.get(key)
    if (!entry) return
    clearTimeout(entry.timer)
    this.disconnectedPlayers.delete(key)
  }

  private loadConfig(): RoomsConfigFile {
    if (!fs.existsSync(this.configPath)) {
      throw new Error(`rooms.config.json not found at ${this.configPath}`)
    }
    // Always re-read to pick up config changes
    const content = fs.readFileSync(this.configPath, 'utf-8')
    this.roomsConfig = JSON.parse(content)
    return this.roomsConfig!
  }

  private findRoomType(roomType: string): RoomTypeDefinition {
    const config = this.loadConfig()
    const def = config.rooms.find(r => r.type === roomType)
    if (!def) {
      throw new Error(`Room type "${roomType}" not found in rooms.config.json`)
    }
    return def
  }

  private async loadRoomClass(def: RoomTypeDefinition): Promise<new (...args: any[]) => GameRoom<any>> {
    // Use Vite's ssrLoadModule for HMR support — each call gets the latest code.
    // room.file paths are project-root-relative (not relative to the config's directory),
    // which matters now that the config can live in rundot/ (or legacy .rundot/).
    // Only deterministic (Syncplay) rooms may omit `file`, and they never reach here.
    if (typeof def.file !== 'string' || def.file.length === 0) {
      throw new Error(`Room type "${def.type}" is missing a "file" (required for non-deterministic rooms)`)
    }
    const filePath = path.resolve(this.projectRoot, def.file)
    const mod = await this.viteServer.ssrLoadModule(filePath)
    const exportName = def.export ?? 'default'
    const RoomClass = mod[exportName]
    if (!RoomClass) {
      const available = Object.keys(mod).filter(k => k !== '__esModule')
      const hint = available.length > 0
        ? ` Available exports: ${available.join(', ')}. Either use "export default class" or set "export": "${available[0]}" in rooms.config.json.`
        : ''
      throw new Error(`Export "${exportName}" not found in ${def.file}.${hint}`)
    }
    return RoomClass
  }

  async createRoom(roomType: string, opts?: CreateRoomOptions): Promise<DevRoomInstance> {
    const def = this.findRoomType(roomType)

    // Singleton: return existing room if one is active. Singletons ignore
    // createOptions/criteria entirely (their identity is the roomType).
    if (def.singleton) {
      const existingId = this.singletonRooms.get(roomType)
      if (existingId) {
        const existing = this.rooms.get(existingId)
        if (existing) return existing
      }
    }

    // Deterministic rooms load no creator file — the injected class runs the
    // engine's built-in input authority. Class is injected (not imported) so this
    // package carries no engine dep; the cast is safe because DevRoomInstance only
    // `new`s it for constructor side-effects, never touching the GameRoom surface.
    let RoomClass: new (...args: any[]) => GameRoom<any>
    if (def.deterministic) {
      if (!this.deterministicRoomClass) {
        throw new Error(
          `${LOG_PREFIX} Room type "${roomType}" is deterministic but no deterministicRoomClass was injected. ` +
          'Pass rundotMultiplayerPlugin({ deterministicRoomClass }) — see the deterministic-room dev docs.',
        )
      }
      RoomClass = this.deterministicRoomClass as unknown as new (...args: any[]) => GameRoom<any>
    } else {
      RoomClass = await this.loadRoomClass(def)
    }
    const roomId = def.singleton ? `singleton:${roomType}` : generateRoomId()
    const roomCode = generateRoomCode()

    const instance = new DevRoomInstance(
      roomId, roomType, roomCode, RoomClass, def.config ?? {}, this.services,
      (playerId) => this.clearGrace(roomId, playerId),
      def.singleton
        ? { deterministic: def.deterministic, metadata: opts?.createOptions?.metadata }
        : {
            criteria: opts?.criteria,
            metadata: opts?.createOptions?.metadata,
            maxPlayersOverride: opts?.createOptions?.maxPlayers,
            isPrivate: opts?.createOptions?.isPrivate,
            deterministic: def.deterministic,
          },
    )
    await instance.initialize()

    this.rooms.set(roomId, instance)
    this.roomCodes.set(roomCode, roomId)

    if (def.singleton) {
      this.singletonRooms.set(roomType, roomId)
    }

    return instance
  }

  async joinOrCreate(roomType: string, opts?: CreateRoomOptions): Promise<DevRoomInstance> {
    // Find an existing room with space. Each room already knows its own
    // maxPlayers (resolved at construction), so no config re-read is needed.
    const singletonId = this.singletonRooms.get(roomType)
    for (const instance of this.rooms.values()) {
      if (
        instance.roomType === roomType &&
        instance.playerCount < instance.maxPlayers &&
        // Singletons are never gated by criteria; standard rooms must satisfy
        // every requested equality constraint.
        (instance.roomId === singletonId || criteriaMatches(instance.criteria, opts?.criteria))
      ) {
        return instance
      }
    }
    // No room found, create one tagged with the requested criteria/createOptions.
    return this.createRoom(roomType, opts)
  }

  joinByCode(roomCode: string): DevRoomInstance {
    const roomId = this.roomCodes.get(roomCode.toUpperCase())
    if (!roomId) {
      throw new Error(`Room code "${roomCode}" not found`)
    }
    const instance = this.rooms.get(roomId)
    if (!instance) {
      throw new Error(`Room "${roomId}" no longer exists`)
    }
    return instance
  }

  getRoom(roomId: string): DevRoomInstance | undefined {
    return this.rooms.get(roomId)
  }

  /**
   * Summaries of the in-memory rooms, mirroring prod's `getUserRooms`.
   * When `profileId` is given, filters to rooms that player is a member of.
   */
  listRooms(profileId?: string): RealtimeRoomSummary[] {
    const now = Date.now()
    const summaries: RealtimeRoomSummary[] = []
    for (const instance of this.rooms.values()) {
      const players = instance.playerIds
      if (profileId && !players.includes(profileId)) continue
      summaries.push({
        roomId: instance.roomId,
        roomCode: instance.roomCode,
        roomType: instance.roomType,
        appId: 'dev-game',
        players,
        maxPlayers: instance.maxPlayers,
        isPrivate: instance.isPrivate,
        status: 'active',
        createdAt: now,
        updatedAt: now,
      })
    }
    return summaries
  }

  /**
   * On socket close, mark the player disconnected and hold their slot for the
   * grace period. Only when the timer fires do we remove the player and dispose
   * an empty non-singleton room — so a reconnect within the window can re-attach.
   *
   * `closingWs` guards against a stale close: on reconnect the player's live
   * socket is swapped before the old socket's close event fires, so a close from
   * a socket that is no longer the player's current one must be ignored.
   */
  async handlePlayerDisconnect(roomId: string, playerId: string, closingWs: WebSocket): Promise<void> {
    const instance = this.rooms.get(roomId)
    if (!instance) return

    if (!instance.isCurrentSocket(playerId, closingWs)) return

    // allowReconnect:false opts out of the grace window — remove immediately.
    if (!instance.allowReconnect) {
      await this.removeAndMaybeDispose(roomId, playerId, 'disconnect')
      return
    }

    const key = this.disconnectKey(roomId, playerId)
    if (this.disconnectedPlayers.has(key)) return

    const graceMs = instance.reconnectTimeoutMs

    // Register the grace timer synchronously — no await between deciding to start
    // grace and storing it — so a reconnect that lands during markDisconnected's
    // await always finds the entry to cancel and can never leave an orphan timer.
    const timer = setTimeout(() => {
      this.clearGrace(roomId, playerId)
      void this.evictPlayer(roomId, playerId)
    }, graceMs)
    this.disconnectedPlayers.set(key, { roomId, playerId, timer })

    await instance.markDisconnected(playerId, graceMs)
  }

  /**
   * Attempt to re-attach a returning player within their grace window.
   * Returns true if the player was reconnected; false if the slot is gone.
   */
  async reconnectPlayer(roomId: string, playerId: string, ws: WebSocket): Promise<boolean> {
    const instance = this.rooms.get(roomId)
    if (!instance || !instance.hasPlayer(playerId)) return false

    this.clearGrace(roomId, playerId)

    await instance.reattach(playerId, ws)
    return true
  }

  private async evictPlayer(roomId: string, playerId: string): Promise<void> {
    const instance = this.rooms.get(roomId)
    if (!instance) return

    // Defense in depth: only evict a player still rostered AND still detached.
    // A reconnect that raced this timer's fire has already flipped the player back
    // to Connected, so it must survive even if the orphan timer reaches here.
    if (!instance.hasPlayer(playerId) || !instance.isDisconnected(playerId)) return

    await this.removeAndMaybeDispose(roomId, playerId, 'disconnect')
  }

  /** Remove a player and dispose the room if it is now empty and not a singleton. */
  private async removeAndMaybeDispose(roomId: string, playerId: string, reason: LeaveReason): Promise<void> {
    const instance = this.rooms.get(roomId)
    if (!instance) return

    await instance.removePlayer(playerId, reason)

    // Don't dispose singleton rooms when empty
    if (instance.isEmpty && !this.singletonRooms.has(instance.roomType)) {
      this.rooms.delete(roomId)
      this.roomCodes.delete(instance.roomCode)
      await instance.dispose()
    }
  }

  /**
   * Enforce the one-presence invariant: remove `profileId` from every room other
   * than `keepRoomId`, clearing any grace timer it holds there (removePlayer routes
   * through clearGrace). Run before EVERY path that places a profile into a room —
   * fresh create/joinByCode/joinOrCreate and the failed-reconnect fallthrough — so a
   * profile is never rostered (live or mid-grace) in two rooms at once.
   */
  async evictStaleMembership(profileId: string, keepRoomId: string): Promise<void> {
    for (const [roomId, instance] of this.rooms) {
      if (roomId === keepRoomId) continue
      if (!instance.hasPlayer(profileId)) continue
      await this.removeAndMaybeDispose(roomId, profileId, 'disconnect')
    }
  }

  async disposeAll(): Promise<void> {
    for (const entry of this.disconnectedPlayers.values()) {
      clearTimeout(entry.timer)
    }
    this.disconnectedPlayers.clear()
    for (const instance of this.rooms.values()) {
      await instance.dispose()
    }
    this.rooms.clear()
    this.roomCodes.clear()
    this.singletonRooms.clear()
  }
}

// ── startDevServer ──────────────────────────────────────────────────────────

interface PlayerConnection {
  ws: WebSocket
  playerId: string
  roomId: string
  authenticated: boolean
}

export function startDevServer(
  viteServer: ViteDevServer,
  options: DevServerOptions = {},
): { close: () => Promise<void> } {
  const port = options.port ?? DEFAULT_DEV_PORT
  const root = options.projectRoot ?? viteServer.config.root
  const configPath = options.configPath ?? path.resolve(root, resolveRoomsConfigPath(root))
  const ticketStore = new DevTicketStore()
  const mock = new MockPlatformServices({ gameConfig: options.gameConfig })
  // Sub-service granularity: a game replaces a whole sub-service object.
  const services: PlatformServices = { ...mock, ...options.mockServices }
  const roomManager = new DevRoomManager(viteServer, configPath, root, services, options.deterministicRoomClass)
  const connections = new Map<WebSocket, PlayerConnection>()

  // ── HTTP Server ──

  const httpServer = http.createServer((req, res) => {
    // CORS preflight
    if (req.method === 'OPTIONS') {
      res.writeHead(204, CORS_HEADERS)
      res.end()
      return
    }

    if (req.method === 'GET' && req.url === '/health') {
      res.writeHead(200, { ...CORS_HEADERS, 'Content-Type': 'application/json' })
      res.end(JSON.stringify({ status: 'ok', mode: 'dev' }))
      return
    }

    if (req.method === 'GET' && req.url?.startsWith('/rooms')) {
      const profileId = new URL(req.url, 'http://localhost').searchParams.get('profileId') ?? undefined
      res.writeHead(200, { ...CORS_HEADERS, 'Content-Type': 'application/json' })
      res.end(JSON.stringify({ rooms: roomManager.listRooms(profileId) }))
      return
    }

    if (req.method === 'POST' && req.url === '/tickets') {
      let body = ''
      req.on('data', (chunk: Buffer) => { body += chunk.toString() })
      req.on('end', () => {
        try {
          const parsed = body ? JSON.parse(body) : {}
          const ticket = ticketStore.create(parsed)
          res.writeHead(200, { ...CORS_HEADERS, 'Content-Type': 'application/json' })
          res.end(JSON.stringify({
            ticketId: ticket.ticketId,
            profileId: ticket.profileId,
            username: ticket.username,
          }))
        } catch {
          res.writeHead(400, { ...CORS_HEADERS, 'Content-Type': 'application/json' })
          res.end(JSON.stringify({ error: 'Invalid request body' }))
        }
      })
      return
    }

    res.writeHead(404, CORS_HEADERS)
    res.end('Not found')
  })

  // ── WebSocket Server ──

  const wss = new WebSocketServer({ server: httpServer, path: '/ws' })

  wss.on('connection', (ws: WebSocket) => {
    const conn: PlayerConnection = { ws, playerId: '', roomId: '', authenticated: false }
    connections.set(ws, conn)

    // Auth timeout
    const authTimer = setTimeout(() => {
      if (!conn.authenticated) {
        sendJson(ws, { type: 'room:error', code: 'UNAUTHORIZED', message: 'Auth timeout' })
        ws.close(4001, 'Auth timeout')
      }
    }, AUTH_TIMEOUT_MS)

    ws.on('message', async (raw: Buffer) => {
      let msg: any
      try {
        msg = JSON.parse(raw.toString())
      } catch {
        sendJson(ws, { type: 'room:error', code: 'INVALID_MESSAGE', message: 'Invalid JSON' })
        return
      }

      // ── Auth message ──
      if (msg.type === 'auth') {
        clearTimeout(authTimer)

        if (conn.authenticated) {
          sendJson(ws, { type: 'room:error', code: 'INVALID_MESSAGE', message: 'Already authenticated' })
          return
        }

        const ticketId = msg.ticket
        if (!ticketId) {
          sendJson(ws, { type: 'room:error', code: 'UNAUTHORIZED', message: 'Missing ticket' })
          ws.close(4001, 'Missing ticket')
          return
        }

        const ticket = ticketStore.redeem(ticketId)
        if (!ticket) {
          sendJson(ws, { type: 'room:error', code: 'UNAUTHORIZED', message: 'Invalid or expired ticket' })
          ws.close(4001, 'Invalid ticket')
          return
        }

        // The response message type and the join side-effects are two independent
        // signals. The message type is dictated by the client's request: a fresh
        // join action (`reconnect` absent) only resolves on `room:joined`, while an
        // explicit `reconnect:true` resolves the transport's reconnection path on
        // `room:reconnected`. The side-effects (onPlayerJoin + room:playerJoined)
        // fire only on a genuine absent→present transition, never for a profile
        // already rostered (live duplicate auth or mid-grace).
        const settleAuth = (instance: DevRoomInstance, type: 'room:joined' | 'room:reconnected'): void => {
          conn.authenticated = true
          conn.playerId = ticket.profileId
          conn.roomId = instance.roomId
          sendJson(ws, {
            type,
            roomCode: instance.roomCode,
            playerId: ticket.profileId,
            _roomId: instance.roomId,
          })
        }

        // Reattach a still-rostered profile (mid-grace or live duplicate): swap the
        // socket, clear grace, suppress onPlayerJoin/room:playerJoined. Distinct
        // from the response type, which the caller chooses from the request.
        const reattachInto = async (instance: DevRoomInstance): Promise<void> => {
          await roomManager.reconnectPlayer(instance.roomId, ticket.profileId, ws)
        }

        // Fresh absent→present join: fires onPlayerJoin + room:playerJoined.
        const joinInto = async (instance: DevRoomInstance): Promise<void> => {
          await instance.joinPlayer({
            id: ticket.profileId,
            username: ticket.username,
            avatarUrl: ticket.avatarUrl,
          }, ws)
        }

        // The instance whose pending-sends outbox was opened (fresh join only).
        // Hoisted so the catch can discard the outbox: `instance` is block-scoped
        // to the try, and conn.roomId isn't set until settleAuth (after the throw
        // site), so neither is reachable from the catch.
        let bufferedInstance: DevRoomInstance | undefined

        try {
          // Explicit reconnect: re-attach to the named room if the player is still
          // rostered (in its grace window) and respond room:reconnected.
          if (msg.reconnect && msg._roomId) {
            const reconnected = await roomManager.reconnectPlayer(msg._roomId, ticket.profileId, ws)
            if (reconnected) {
              // Reattached to the named room — reconcile away any stale membership the
              // profile may still hold in another room so the one-presence invariant holds.
              await roomManager.evictStaleMembership(ticket.profileId, msg._roomId)
              settleAuth(roomManager.getRoom(msg._roomId)!, 'room:reconnected')
              return
            }
          }

          // Resolve room based on action
          let instance: DevRoomInstance
          const action = msg.action ?? ticket.action ?? 'joinOrCreate'

          // criteria/createOptions ride the ticket and apply only to fresh
          // create / joinOrCreate — not reconnect or joinByCode.
          const roomOpts: CreateRoomOptions = { criteria: ticket.criteria, createOptions: ticket.createOptions }
          if (action === 'create') {
            instance = await roomManager.createRoom(ticket.roomType, roomOpts)
          } else if (action === 'joinByCode') {
            const code = msg.roomCode ?? ticket.roomCode
            if (!code) {
              sendJson(ws, { type: 'room:error', code: 'ROOM_NOT_FOUND', message: 'Missing room code' })
              ws.close(4004, 'Missing room code')
              return
            }
            instance = roomManager.joinByCode(code)
          } else {
            instance = await roomManager.joinOrCreate(ticket.roomType, roomOpts)
          }

          // Enforce one presence per profile on EVERY join path: before placing the
          // profile into the resolved room, drop any roster/grace membership it holds
          // in any other room. This covers fresh create/joinByCode/joinOrCreate as
          // well as the failed-explicit-reconnect fallthrough — none can double-roster.
          await roomManager.evictStaleMembership(ticket.profileId, instance.roomId)

          // A fresh join action (no reconnect flag) must always resolve room:joined,
          // because the client awaits only room:joined. If the profile is already
          // rostered (mid-grace or live) we still reattach to suppress a duplicate
          // onPlayerJoin, but the response stays room:joined.
          // Only a fresh join opens a pending-sends outbox (it runs onPlayerJoin);
          // the reattach path does not, so it needs no flush.
          const freshJoin = !instance.hasPlayer(ticket.profileId)
          if (freshJoin) {
            // joinPlayer opens the outbox before onPlayerJoin runs; record the
            // instance so the catch can discard it if the join throws.
            bufferedInstance = instance
            await joinInto(instance)
          } else {
            await reattachInto(instance)
          }

          settleAuth(instance, 'room:joined')

          // Replays buffered by onPlayerJoin's sendTo hit the wire AFTER the
          // room:joined ack — the client ignores frames until that ack.
          if (freshJoin) {
            instance.flushJoinSends(ticket.profileId)
          }
        } catch (err: any) {
          // A fresh join may have opened an outbox before throwing; discard it so a
          // later join for the same profile can't flush stale frames. reattach/
          // explicit-reconnect paths never set bufferedInstance, so this is skipped
          // there.
          bufferedInstance?.discardJoinSends(ticket.profileId)
          const message = err?.message ?? 'Failed to join room'
          const code = message.includes('not found') ? 'ROOM_NOT_FOUND' : 'INTERNAL_ERROR'
          sendJson(ws, { type: 'room:error', code, message })
          ws.close(4000, message)
        }
        return
      }

      // ── All messages below require auth ──

      if (!conn.authenticated) {
        sendJson(ws, { type: 'room:error', code: 'UNAUTHORIZED', message: 'Not authenticated' })
        return
      }

      // ── Ping ──
      if (msg.type === 'ping') {
        sendJson(ws, { type: 'pong', ts: msg.ts, serverTs: Date.now() })
        return
      }

      // ── Game message ──
      if (msg.type === 'message') {
        const instance = roomManager.getRoom(conn.roomId)
        if (instance) {
          try {
            await instance.handleMessage(conn.playerId, msg.msgType, msg.data)
          } catch (err: any) {
            console.error(`${LOG_PREFIX} Error handling message:`, err?.message)
          }
        }
        return
      }
    })

    ws.on('close', async () => {
      clearTimeout(authTimer)
      connections.delete(ws)

      if (conn.authenticated && conn.roomId) {
        await roomManager.handlePlayerDisconnect(conn.roomId, conn.playerId, ws)
      }
    })

    ws.on('error', (err) => {
      console.error(`${LOG_PREFIX} WebSocket error:`, err.message)
    })
  })

  // ── Start listening ──

  httpServer.listen(port)

  // ── Watch room files for changes ──

  if (fs.existsSync(configPath)) {
    try {
      const config: RoomsConfigFile = JSON.parse(fs.readFileSync(configPath, 'utf-8'))
      // Deterministic (Syncplay) rooms carry no `file` — the built-in authority
      // is loaded in-process, so there is nothing on disk to watch. Skip them so
      // path.resolve doesn't throw on `undefined` and silently kill the watcher
      // for the creator's other room files.
      const roomFiles = config.rooms
        .filter(r => typeof r.file === 'string' && r.file.length > 0)
        .map(r => path.resolve(root, r.file as string))
      for (const file of roomFiles) {
        viteServer.watcher.add(file)
      }
    } catch {
      // Config not yet ready, that's fine
    }
  }

  // ── Cleanup ──

  return {
    close: async () => {
      // Forceful: wss.close() and httpServer.close() only stop NEW connections
      // and then wait on existing ones — a lingering client socket would pin
      // the dev process open past vite's own shutdown.
      for (const client of wss.clients) client.terminate()
      wss.close()
      httpServer.closeAllConnections()
      httpServer.close()
      await roomManager.disposeAll()
    },
  }
}

function sendJson(ws: WebSocket, msg: object): void {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(msg))
  }
}
