import type { Protocol } from '../shared'
import type { Player, PlayerJoinData } from './Player'
import type { RoomConfig } from './RoomConfig'
import type { Clock, ClockSnapshot } from './Clock'
import type { Logger } from './Logger'
import type { PlatformServices } from './PlatformServices'

export const SYSTEM_MSG_DISCONNECTED = '__system:disconnected'
export const SYSTEM_MSG_RECONNECTED = '__system:reconnected'

/**
 * Hard cap (bytes) for a single realtime WS broadcast frame, mirroring
 * mp-room-server `WebSocketGateway` `maxPayload` (16 KiB). A world/economy delta
 * larger than this is never chunked or dropped — see `GameRoom.broadcastDelta`,
 * which falls back to a resync signal (Phase 4 / AC-7).
 *
 * This value is the contract floor mp-room-server must satisfy
 * (`WS_BROADCAST_CONTRACT_FLOOR` in its `config/environment.ts`); the gateway
 * fails fast at boot if its configured `maxMessageSize` drops below it, so the
 * SDK can never approve a frame the gateway would silently drop.
 */
export const MAX_BROADCAST_BYTES = 16 * 1024

class JoinRejectedError extends Error {
  constructor(reason: string) {
    super(reason)
    this.name = 'JoinRejectedError'
  }
}

/**
 * Options passed to reject() to deny a player join.
 */
export interface RejectOptions {
  reason?: string
}

/**
 * Reason a player left the room.
 */
export type LeaveReason = 'leave' | 'disconnect' | 'kick'

/**
 * Result of a player join attempt.
 */
export type JoinResult =
  | { accepted: true; player: Player }
  | { accepted: false; reason: string }

/**
 * Bidirectional protocol interface between harness and GameRoom.
 *
 * - **Outbound** methods are set by the harness before construction, called by GameRoom.
 * - **Inbound** callbacks are set by GameRoom's constructor, called by the harness.
 * - **Serialization accessors** are set by GameRoom, called by the harness.
 */
export interface RoomProtocol {
  // ── Outbound — set by harness, called by GameRoom ──
  broadcast(type: string, data: unknown): void
  sendTo(playerId: string, type: string, data: unknown): void
  kick(playerId: string, reason?: string): void
  lock(): void
  unlock(): void
  persist(state: Record<string, unknown>): void

  // ── Inbound — set by GameRoom constructor, called by harness ──
  handleCreate: () => Promise<void>
  handleRestore: (snapshot: Record<string, unknown>, bundleVersion?: string, currentBundleVersion?: string) => Promise<void>
  handleJoin: (data: PlayerJoinData) => Promise<JoinResult>
  handleMessage: (playerId: string, msgType: string, data: unknown) => Promise<void>
  handleLeave: (playerId: string, reason: LeaveReason) => Promise<void>
  handleDispose: () => Promise<void>
  handleTick: () => Promise<void>

  // ── Serialization accessors — set by GameRoom, called by harness ──
  serializePersistState: () => Record<string, unknown>
  getLocked: () => boolean
  getPlayers: () => ReadonlyMap<string, Player>
}

/**
 * Context provided to a GameRoom upon instantiation by the harness.
 */
export interface GameRoomProps {
  protocol: RoomProtocol
  roomId: string
  roomType: string
  config: Readonly<RoomConfig>
  players: Map<string, Player>
  clock: Clock
  log: Logger
  services: PlatformServices
}

/**
 * Inbound message — wraps the message payload with the sender.
 * Used in `onGameMessage`. Switch on `payload.type` to narrow the payload.
 */
export type GameMessage<P extends Protocol> = {
  sender: Player
  payload: P
}

/**
 * Abstract base class for server-authoritative game rooms.
 *
 * Game developers extend this class to implement their game logic.
 * The harness instantiates it and wires up the internal `RoomProtocol`.
 *
 * Type parameters:
 * - `P` — Discriminated union of game message types (must have `{ type: string }`).
 *
 * Persistence:
 * - `getPersistState()` — Override to return data to persist to Firestore for crash recovery.
 *
 * @example
 * ```ts
 * import { GameRoom, GameRoomProps } from '@series-inc/rundot-game-sdk/mp-server'
 *
 * // -- Messages --
 * interface MoveMessage { type: 'move'; x: number; y: number }
 * interface ChatMessage { type: 'chat'; text: string }
 * type MyMessages = MoveMessage | ChatMessage
 *
 * export default class TicTacToe extends GameRoom<MyMessages> {
 *   private board: string[] = Array(9).fill('')
 *   private currentTurn: 'X' | 'O' = 'X'
 *   private moveHistory: Array<{ player: string; pos: number; ts: number }> = []
 *
 *   protected getPersistState() {
 *     return {
 *       board: this.board,
 *       currentTurn: this.currentTurn,
 *       moveHistory: this.moveHistory,
 *     }
 *   }
 *
 *   onCreate() { this.log.info('Room created') }
 *
 *   onPlayerJoin(player: Player) {
 *     this.log.info('Player joined', { playerId: player.id })
 *   }
 *
 *   onGameMessage(message) {
 *     const { sender, payload } = message
 *     switch (payload.type) {
 *       case 'move':
 *         this.board[payload.x] = 'X'
 *         this.moveHistory.push({ player: sender.id, pos: payload.x, ts: Date.now() })
 *         this.broadcast({ type: 'move', x: payload.x, y: payload.y })
 *         break
 *       case 'chat':
 *         this.broadcast({ type: 'chat', text: payload.text })
 *         break
 *       case 'craft':
 *         // Platform services: run a simulation recipe on behalf of the sender
 *         await this.services.simulation.executeRecipe(sender.id, payload.recipeId)
 *         break
 *     }
 *   }
 *   onPlayerLeave(player: Player, reason: LeaveReason) { ... }
 * }
 * ```
 */
export abstract class GameRoom<P extends Protocol> {
  // ── Context properties ──

  /** @internal Protocol wired by the harness */
  private readonly _protocol: RoomProtocol

  /** Room identifier */
  readonly roomId: string

  /** Room type name from rooms.config.json */
  readonly roomType: string

  /** Room configuration */
  readonly config: Readonly<RoomConfig>

  /** Connected players (Map<playerId, Player>) */
  get players(): ReadonlyMap<string, Player> {
    return this._players
  }
  private readonly _players: Map<string, Player>

  /** Managed timer system with named handles */
  readonly clock: Clock

  /** Structured logger */
  readonly log: Logger

  /** Platform services bridge (notifications, leaderboard, UGC, simulation, game config) */
  readonly services: PlatformServices

  /** Whether the room is locked (no new joins) */
  private _locked = false

  /**
   * Override to return the data to persist to Firestore for crash recovery.
   * Default: nothing persisted.
   */
  protected getPersistState(): Record<string, unknown> {
    return {}
  }

  protected constructor(context: GameRoomProps) {
    this._protocol = context.protocol
    this.roomId = context.roomId
    this.roomType = context.roomType
    this.config = context.config
    this._players = context.players
    this.clock = context.clock
    this.log = context.log
    this.services = context.services

    // Wire inbound handlers
    context.protocol.handleCreate = () => this.handleCreate()
    context.protocol.handleRestore = (snapshot, bundleVersion, currentBundleVersion) =>
      this.handleRestore(snapshot, bundleVersion, currentBundleVersion)
    context.protocol.handleJoin = (data) => this.handleJoin(data)
    context.protocol.handleMessage = (playerId, msgType, data) =>
      this.handleMessage(playerId, msgType, data)
    context.protocol.handleLeave = (playerId, reason) =>
      this.handleLeave(playerId, reason)
    context.protocol.handleDispose = () => this.handleDispose()
    context.protocol.handleTick = () => this.handleTick()

    // Wire serialization accessors
    context.protocol.serializePersistState = () => this.serializePersistState()
    context.protocol.getLocked = () => this.locked
    context.protocol.getPlayers = () => this.players
  }

  // ── Lifecycle Hooks (override in subclass) ──

  /**
   * Called when the room is first created.
   * Use this to initialize game state.
   */
  protected onCreate?(): void | Promise<void>

  /**
   * Called when a room is restored from a persisted snapshot (crash recovery).
   * The snapshot contains everything returned by `getPersistState()`.
   * Use this hook to manually restore your state from the snapshot.
   * @param snapshot The persisted data from `getPersistState()`
   */
  protected onRestore?(snapshot: Record<string, unknown>): void | Promise<void>

  /**
   * Called when a room is restored but the bundle version has changed.
   * Use this to migrate state between versions.
   * @param snapshot The persisted state data
   * @param oldVersion Previous bundle version
   */
  protected onMigrate?(
    snapshot: Record<string, unknown>,
    oldVersion: string,
  ): void | Promise<void>

  /**
   * Called when a player requests to join the room.
   * Call `this.reject()` to deny the join.
   */
  protected onPlayerJoin?(player: Player): void | Promise<void>

  /**
   * Called when a player sends a typed game message.
   * Use `switch (message.type)` to narrow the payload fields.
   * Access the sender via `message.sender`.
   * @param message Discriminated union with sender, type, and flattened payload
   */
  protected onGameMessage?(message: GameMessage<P>): void | Promise<void>

  /**
   * Called when a player leaves the room (voluntarily, disconnect, or kick).
   */
  protected onPlayerLeave?(
    player: Player,
    reason: LeaveReason,
  ): void | Promise<void>

  /**
   * Called when the room is about to be disposed.
   * Use this for final cleanup.
   */
  protected onDispose?(): void | Promise<void>

  /**
   * Called on each server-owned clock tick while the room is WARM (has at least
   * one member). Configure the cadence via the room type's `tickInterval`
   * (seconds). An idle room freezes (no ticks); on resume, drive catch-up from
   * absolute expiry timestamps rather than counting ticks. Use this to advance
   * server-authoritative timed progression (e.g. settle expired simulation
   * recipes) without relying on a client read.
   */
  protected onTick?(): void | Promise<void>

  // ── Private Inbound Handlers ──

  private async handleCreate(): Promise<void> {
    await this.onCreate?.()
  }

  private async handleTick(): Promise<void> {
    await this.onTick?.()
  }

  private async handleRestore(
    snapshot: Record<string, unknown>,
    bundleVersion?: string,
    currentBundleVersion?: string,
  ): Promise<void> {
    const snapshotState = (snapshot.state as Record<string, unknown>) ?? {}
    const clockSnapshot = (snapshot.clockSnapshot as ClockSnapshot) ?? null

    const isMigration = bundleVersion && bundleVersion !== currentBundleVersion

    if (isMigration && this.onMigrate) {
      this.log.info('Migrating room state', {
        fromVersion: bundleVersion,
        toVersion: currentBundleVersion,
      })
      await this.onMigrate(snapshotState, bundleVersion)
    } else if (this.onRestore) {
      await this.onRestore(snapshotState)
    }

    // Auto-restore clock timings from snapshot so timers resume where they
    // left off rather than restarting from zero.
    if (clockSnapshot) {
      this.clock.restoreTimings(clockSnapshot)
    }
  }

  private async handleJoin(data: PlayerJoinData): Promise<JoinResult> {
    const player: Player = {
      id: data.id,
      username: data.username,
      avatarUrl: data.avatarUrl,
      joinedAt: Date.now(),
      connected: true,
    }

    this._players.set(data.id, player)
    try {
      await this.onPlayerJoin?.(player)
      return { accepted: true, player }
    } catch (err: unknown) {
      this._players.delete(data.id)
      if (err instanceof JoinRejectedError) {
        return { accepted: false, reason: err.message }
      }
      throw err
    }
  }

  private handleSystemMessage(
    player: Player | undefined,
    playerId: string,
    msgType: string,
  ): boolean {
    if (msgType === SYSTEM_MSG_DISCONNECTED) {
      if (player) {
        player.connected = false
        this.log.info('Player disconnected (grace period)', { playerId })
      }
      return true
    }
    if (msgType === SYSTEM_MSG_RECONNECTED) {
      if (player) {
        player.connected = true
        this.log.info('Player reconnected', { playerId })
      }
      return true
    }
    return false
  }

  private async handleMessage(
    playerId: string,
    msgType: string,
    data: unknown,
  ): Promise<void> {
    const player = this._players.get(playerId)

    if (this.handleSystemMessage(player, playerId, msgType)) return

    if (!player) {
      this.log.warn('Message from unknown player', { playerId, msgType })
      return
    }

    if (this.onGameMessage) {
      await this.onGameMessage({
        sender: player,
        payload: { ...(data as object), type: msgType } as P,
      })
    }
  }

  private async handleLeave(
    playerId: string,
    reason: LeaveReason,
  ): Promise<void> {
    const player = this._players.get(playerId)
    if (!player) return

    this._players.delete(playerId)

    await this.onPlayerLeave?.(player, reason)

    this.log.info('Player left', { playerId, reason })
  }

  private async handleDispose(): Promise<void> {
    await this.onDispose?.()
    this.clock.dispose()
  }

  // ── Protected API (called by game developer) ──

  /**
   * Whether the room is currently locked.
   */
  get locked(): boolean {
    return this._locked
  }

  /**
   * Number of connected players.
   */
  get playerCount(): number {
    return this.players.size
  }

  /**
   * Broadcast a typed message to all connected clients.
   */
  protected broadcast(message: P): void {
    const { type, ...data } = message
    this._protocol.broadcast(type, data)
  }

  /**
   * Send a typed message to a specific player.
   */
  protected sendTo(playerId: string, message: P): void {
    const { type, ...data } = message
    this._protocol.sendTo(playerId, type, data)
  }

  /**
   * Server-authoritative world/economy delta broadcast (Phase 4 / Req 7, AC-7).
   *
   * Pushes a server-computed delta to the room's current members only (the
   * transport broadcasts to connected players, so non-members never receive it —
   * AC-6's "client cannot assert a shared outcome" is structural: deltas
   * originate from authoritative server state, never from client input).
   *
   * The realtime WS frame is hard-capped at {@link MAX_BROADCAST_BYTES} (mirrors
   * mp-room-server `WebSocketGateway` `maxPayload`). A delta that would exceed the
   * cap is **never chunked or silently dropped**: the server instead broadcasts a
   * lightweight `resync` signal telling members to re-pull authoritative state
   * (e.g. via `getState`). Returns what was sent and the measured byte size so
   * callers/tests can assert the branch taken.
   */
  protected broadcastDelta(
    delta: unknown,
    opts?: { deltaType?: string; resyncType?: string },
  ): { sent: 'delta' | 'resync'; bytes: number } {
    const deltaType = opts?.deltaType ?? 'world:delta'
    const resyncType = opts?.resyncType ?? 'world:resync'
    // Measure the exact wire frame mp-room-server emits for a broadcast
    // (`{ type:'room:broadcast', msgType, data }`, see RoomInstance.handleBroadcast),
    // not just the inner delta — otherwise the envelope overhead could push an
    // "approved" frame past the cap on the wire. GameRoom runs server-side in a
    // Node worker, so Buffer is the canonical UTF-8 byte measure.
    const frame = { type: 'room:broadcast', msgType: deltaType, data: { delta } }
    const bytes = Buffer.byteLength(JSON.stringify(frame), 'utf8')

    if (bytes <= MAX_BROADCAST_BYTES) {
      this._protocol.broadcast(deltaType, { delta })
      return { sent: 'delta', bytes }
    }

    this.log.warn('World delta exceeds WS frame cap — broadcasting resync instead', {
      bytes,
      cap: MAX_BROADCAST_BYTES,
    })
    this._protocol.broadcast(resyncType, { reason: 'delta_too_large' })
    return { sent: 'resync', bytes }
  }

  /**
   * Kick a player from the room.
   */
  protected kick(playerId: string, reason?: string): void {
    this._protocol.kick(playerId, reason)
  }

  /**
   * Lock the room — prevent new players from joining.
   */
  protected lock(): void {
    this._locked = true
    this._protocol.lock()
  }

  /**
   * Unlock the room — allow new players to join.
   */
  protected unlock(): void {
    this._locked = false
    this._protocol.unlock()
  }

  /**
   * Immediately persist `getPersistState()` data to Firestore.
   * (Also persists automatically on a debounced interval if autoPersist is enabled.)
   */
  protected save(): void {
    this._protocol.persist(this.getPersistState())
  }

  /**
   * Reject a player join (call inside onPlayerJoin).
   * Throws an error that the harness catches to deny the join.
   */
  protected reject(options?: RejectOptions): never {
    throw new JoinRejectedError(options?.reason ?? 'Join rejected')
  }

  // ── Internal Serialization ──

  /**
   * Returns the data from `getPersistState()` for Firestore.
   */
  private serializePersistState(): Record<string, unknown> {
    return this.getPersistState()
  }
}
